INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM21GC7WY', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 2, 'mcq', E'A researcher surveys a random sample of $340$ households in a county and finds that $37\\%$ compost their food waste, with a margin of error of $5.2\\%$ at the $95\\%$ confidence level. There are $8{,}400$ households in the county. Based on this survey, which of the following is a plausible estimate for the total number of households in the county that compost their food waste?', NULL, $lyceon_json$[{"key":"A","text":"$2{,}268$"},{"key":"B","text":"$3{,}108$"},{"key":"C","text":"$3{,}864$"},{"key":"D","text":"$4{,}536$"}]$lyceon_json$::jsonb, 'B', NULL, E'The confidence interval for the proportion is $37\\% \\pm 5.2\\%$, which gives a range from $31.8\\%$ to $42.2\\%$. Applying this to the $8{,}400$ households yields a plausible range of $0.318 \\times 8{,}400 = 2{,}671$ to $0.422 \\times 8{,}400 = 3{,}545$. The point estimate $0.37 \\times 8{,}400 = 3{,}108$ falls within this interval and is the most plausible estimate. The value $2{,}268$ corresponds to about $27\\%$, below the lower bound. The value $3{,}864$ corresponds to about $46\\%$, above the upper bound. The value $4{,}536$ corresponds to $54\\%$, far outside the plausible range.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 80, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM22B9WSR', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 2, 'grid_in', E'Line $m$ passes through the points $(-3, 11)$ and $(5, -13)$. What is the $x$-coordinate of the $x$-intercept of line $m$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '2/3', ARRAY['2/3', '0.666', '.666', '0.667', '.667'], E'The slope of line $m$ is $\\frac{-13 - 11}{5 - (-3)} = \\frac{-24}{8} = -3$. Using point-slope form with the point $(-3, 11)$: $y - 11 = -3(x - (-3))$, which simplifies to $y - 11 = -3(x + 3) = -3x - 9$, so $y = -3x + 2$. Setting $y = 0$ to find the $x$-intercept gives $0 = -3x + 2$, so $3x = 2$ and $x = \\frac{2}{3}$. The $x$-coordinate of the $x$-intercept is $\\frac{2}{3}$.', NULL, NULL, 'draft', 1, 80, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM22YJH5C', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 1, 'mcq', E'A recipe calls for $7$ cups of broth to make $42$ servings of soup. How many cups of broth are needed to make $18$ servings of soup?', NULL, $lyceon_json$[{"key":"A","text":"$2$"},{"key":"B","text":"$3$"},{"key":"C","text":"$6$"},{"key":"D","text":"$7$"}]$lyceon_json$::jsonb, 'B', NULL, E'The ratio of broth to servings is $\\frac{7}{42} = \\frac{1}{6}$ cup per serving. For $18$ servings: $\\frac{1}{6} \\times 18 = 3$ cups. The value $2$ results from an arithmetic slip in the division. The value $6$ results from inverting the ratio and computing $\\frac{6}{1} \\times 1$ or confusing the unit rate. The value $7$ comes from restating the original broth quantity without adjusting for the different number of servings.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM237J296', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 2, 'mcq', E'A surveyor stands $85$ meters from the base of a vertical tower and measures the angle of elevation to the top of the tower to be $29^\\circ$. Which of the following expressions gives the height, in meters, of the tower?', NULL, $lyceon_json$[{"key":"A","text":"$85 \\sin(29^\\circ)$"},{"key":"B","text":"$85 \\cos(29^\\circ)$"},{"key":"C","text":"$85 \\tan(29^\\circ)$"},{"key":"D","text":"$\\frac{85}{\\tan(29^\\circ)}$"}]$lyceon_json$::jsonb, 'C', NULL, E'The tower height is the side opposite the $29^\\circ$ angle, and the $85$-meter distance is the side adjacent to it. The tangent ratio gives $\\tan(29^\\circ) = \\frac{\\text{height}}{85}$, so the height equals $85 \\tan(29^\\circ)$. Using $85 \\sin(29^\\circ)$ incorrectly treats the $85$-meter distance as the hypotenuse rather than the adjacent side. Using $85 \\cos(29^\\circ)$ confuses the cosine ratio with the tangent in the adjacent-opposite relationship. Using $\\frac{85}{\\tan(29^\\circ)}$ inverts the tangent ratio, which would give the adjacent side if the opposite side were $85$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM23ACL9G', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 1, 'mcq', E'What is the solution to the inequality $-5x + 13 \\geq -17$?', NULL, $lyceon_json$[{"key":"A","text":"$x \\leq 6$"},{"key":"B","text":"$x \\geq 6$"},{"key":"C","text":"$x \\leq -6$"},{"key":"D","text":"$x \\geq -6$"}]$lyceon_json$::jsonb, 'A', NULL, E'Subtracting 13 from both sides gives $-5x \\geq -30$. Dividing both sides by $-5$ and reversing the inequality sign yields $x \\leq 6$. The distractor $x \\geq 6$ results from forgetting to flip the inequality when dividing by a negative number. The distractor $x \\leq -6$ comes from an arithmetic error in the sign of the constant after division. The distractor $x \\geq -6$ combines both the sign error on the constant and the failure to reverse the inequality direction.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM24CB3RY', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 3, 'grid_in', E'A city''s population decreased by $6\\%$ from 2022 to 2023 and then increased by $11\\%$ from 2023 to 2024. If the population was $47{,}000$ in 2022, what was the population in 2024, rounded to the nearest whole number?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '49040', ARRAY['49040'], E'After a $6\\%$ decrease: $47{,}000 \\times 0.94 = 44{,}180$. After an $11\\%$ increase: $44{,}180 \\times 1.11 = 49{,}039.8$. Rounded to the nearest whole number, the population is $49{,}040$. A common error is computing a net $5\\%$ increase ($47{,}000 \\times 1.05 = 49{,}350$), which ignores that percentage changes compound rather than simply add. Another error is applying both percentages to the original value separately.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM24H4PWX', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 3, 'grid_in', E'At a company, $40\\%$ of employees work remotely. Of those who work remotely, $85\\%$ report high job satisfaction. Of those who do not work remotely, $60\\%$ report high job satisfaction. If an employee chosen at random reports high job satisfaction, what is the probability, rounded to the nearest hundredth, that the employee works remotely?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '0.49', ARRAY['0.49', '.49'], E'Let $R$ be the event that an employee works remotely and $S$ be the event of high satisfaction. We are given $P(R) = 0.40$, $P(S \\mid R) = 0.85$, and $P(S \\mid R^c) = 0.60$. By the law of total probability, $P(S) = P(S \\mid R) \\cdot P(R) + P(S \\mid R^c) \\cdot P(R^c) = 0.85 \\times 0.40 + 0.60 \\times 0.60 = 0.34 + 0.36 = 0.70$. By Bayes'' theorem, $P(R \\mid S) = \\frac{P(S \\mid R) \\cdot P(R)}{P(S)} = \\frac{0.34}{0.70} \\approx 0.4857$, which rounds to $0.49$.', NULL, NULL, 'draft', 1, 110, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM251WIR0', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 2, 'mcq', E'A circle has center $(-7, 4)$ and passes through the point $(5, -1)$. What is the equation of the circle?', NULL, $lyceon_json$[{"key":"A","text":"$(x + 7)^2 + (y - 4)^2 = 169$"},{"key":"B","text":"$(x - 7)^2 + (y + 4)^2 = 169$"},{"key":"C","text":"$(x + 7)^2 + (y - 4)^2 = 13$"},{"key":"D","text":"$(x - 7)^2 + (y + 4)^2 = 13$"}]$lyceon_json$::jsonb, 'A', NULL, E'The radius is the distance from the center $(-7, 4)$ to $(5, -1)$: $r = \\sqrt{(5 - (-7))^2 + (-1 - 4)^2} = \\sqrt{144 + 25} = \\sqrt{169} = 13$. The standard form is $(x - h)^2 + (y - k)^2 = r^2$, giving $(x + 7)^2 + (y - 4)^2 = 169$. The option $(x - 7)^2 + (y + 4)^2 = 169$ uses the wrong signs for the center coordinates, writing $(x - (-7))$ as $(x - 7)$. The option with right side $13$ uses the radius itself instead of $r^2 = 169$, forgetting to square the radius. The option combining both errors has wrong signs and an unsquared radius.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM25IK4IQ', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 3, 'grid_in', E'A cartographer uses a map scale where $3$ centimeters represents $19$ kilometers. On the map, the distance between two towns is $8.7$ centimeters. A road between the two towns follows a path that is $1.4$ times the straight-line distance. What is the actual length of the road, in kilometers, rounded to the nearest whole number?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '77', ARRAY['77'], E'The scale is $\\frac{19}{3}$ km per cm. The straight-line distance is $8.7 \\times \\frac{19}{3} = \\frac{165.3}{3} = 55.1$ km. The road is $1.4$ times the straight-line distance: $55.1 \\times 1.4 = 77.14$ km. Rounded to the nearest whole number, the road is $77$ km. A common error is forgetting to apply the $1.4$ multiplier, giving $55$ km. Another error is miscomputing the scale conversion by dividing instead of multiplying.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM25UH1HH', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 1, 'mcq', E'What is the $y$-intercept of the line $7x + 11y = 77$?', NULL, $lyceon_json$[{"key":"A","text":"$7$"},{"key":"B","text":"$11$"},{"key":"C","text":"$77$"},{"key":"D","text":"$\\frac{77}{7}$"}]$lyceon_json$::jsonb, 'A', NULL, E'The $y$-intercept occurs when $x = 0$. Substituting: $7(0) + 11y = 77$, so $11y = 77$ and $y = 7$. The value 11 results from dividing 77 by 7 (finding the $x$-intercept coefficient) instead of dividing by 11. The value 77 ignores the coefficient of $y$ entirely. The value $\\frac{77}{7}$ finds the $x$-intercept instead of the $y$-intercept.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM26W3R4Q', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 2, 'mcq', E'A fitness company randomly assigns $120$ volunteers to one of two groups. Group 1 follows a new stretching routine for $8$ weeks, while Group 2 follows no specific routine. At the end of $8$ weeks, Group 1 shows significantly greater flexibility improvement than Group 2. Which of the following conclusions is best supported by this study?', NULL, $lyceon_json$[{"key":"A","text":"The stretching routine causes improved flexibility among the volunteers in the study."},{"key":"B","text":"The stretching routine will improve flexibility for all adults."},{"key":"C","text":"People who stretch regularly are more flexible than people who do not stretch."},{"key":"D","text":"The stretching routine is associated with flexibility improvement, but a causal relationship cannot be established."}]$lyceon_json$::jsonb, 'A', NULL, E'Because the study used random assignment to treatment and control groups, a causal conclusion can be drawn for the participants in the study. The stretching routine can be said to cause the improved flexibility among these volunteers. The conclusion that the routine will work for all adults overgeneralizes — the participants were volunteers, not a random sample of all adults, so generalizability to the broader population is limited. The statement about people who stretch regularly describes an observational relationship, not the experimental finding. The claim that causation cannot be established is incorrect because random assignment specifically enables causal inference.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM27PBDDE', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 1, 'mcq', E'The function $f$ is defined by $f(x) = -4x + 23$. What is the value of $f(6)$?', NULL, $lyceon_json$[{"key":"A","text":"$-1$"},{"key":"B","text":"$47$"},{"key":"C","text":"$1$"},{"key":"D","text":"$-47$"}]$lyceon_json$::jsonb, 'A', NULL, E'Substituting $x = 6$: $f(6) = -4(6) + 23 = -24 + 23 = -1$. The value 47 results from treating $-4(6)$ as $+24$, giving $24 + 23 = 47$, which is a sign error on the leading coefficient. The value 1 comes from computing $|-24 + 23| = 1$, incorrectly taking the absolute value of the result. The value $-47$ comes from computing $-(24 + 23) = -47$, as if the negative sign applies to the entire expression rather than just the first term.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 40, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM28DNWRH', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 2, 'mcq', E'A machine fills $91$ bottles in $13$ minutes. A second machine fills $85$ bottles in $17$ minutes. Working together at their respective constant rates, how many bottles do the two machines fill in $51$ minutes?', NULL, $lyceon_json$[{"key":"A","text":"$306$"},{"key":"B","text":"$357$"},{"key":"C","text":"$408$"},{"key":"D","text":"$612$"}]$lyceon_json$::jsonb, 'D', NULL, E'Machine 1 fills $\\frac{91}{13} = 7$ bottles per minute. Machine 2 fills $\\frac{85}{17} = 5$ bottles per minute. Together they fill $7 + 5 = 12$ bottles per minute. In $51$ minutes: $12 \\times 51 = 612$ bottles. The value $306$ comes from averaging the two rates as $6$ bottles per minute and computing $6 \\times 51$. The value $357$ comes from using only Machine 1''s rate: $7 \\times 51 = 357$. The value $408$ comes from an arithmetic slip such as computing $8 \\times 51 = 408$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM28HC8HD', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 1, 'mcq', E'What is the value of $x$ in the equation $8x + 23 = 71$?', NULL, $lyceon_json$[{"key":"A","text":"$6$"},{"key":"B","text":"$8$"},{"key":"C","text":"$12$"},{"key":"D","text":"$48$"}]$lyceon_json$::jsonb, 'A', NULL, E'Subtracting 23 from both sides: $8x = 48$. Dividing by 8: $x = 6$. The value 8 results from an arithmetic error in the division step. The value 12 comes from incorrectly subtracting 23 from 71 to get 96, then dividing by 8. The value 48 comes from stopping after subtracting 23 without dividing by 8.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM29NIZ06', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 3, 'mcq', E'The function $g$ is linear, with $g(1) = 5$ and $g(-6) = 33$. For what value of $x$ does $g(x) = 0$?', NULL, $lyceon_json$[{"key":"A","text":"$-\\frac{9}{4}$"},{"key":"B","text":"$\\frac{5}{4}$"},{"key":"C","text":"$\\frac{9}{4}$"},{"key":"D","text":"$\\frac{33}{4}$"}]$lyceon_json$::jsonb, 'C', NULL, E'The slope of $g$ is $\\frac{33 - 5}{-6 - 1} = \\frac{28}{-7} = -4$. Using the point $(1, 5)$: $g(x) = -4(x - 1) + 5 = -4x + 4 + 5 = -4x + 9$. Setting $g(x) = 0$: $-4x + 9 = 0$, so $4x = 9$ and $x = \\frac{9}{4}$. The value $-\\frac{9}{4}$ results from a sign error in the final step, dividing $-9$ by $4$ instead of $9$ by $4$. The value $\\frac{5}{4}$ comes from using only the $y$-value from the first point, solving $-4x + 5 = 0$ instead of using the correct $y$-intercept of 9, which represents incomplete computation of the linear function. The value $\\frac{33}{4}$ results from incorrectly using $g(-6) = 33$ as the $y$-intercept, solving $-4x + 33 = 0$ to get $x = \\frac{33}{4}$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM29SVP4S', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 1, 'mcq', E'Which of the following expressions is equivalent to $3x^2 + 12x - 15$?', NULL, $lyceon_json$[{"key":"A","text":"$3(x + 5)(x - 1)$"},{"key":"B","text":"$3(x - 5)(x + 1)$"},{"key":"C","text":"$(3x + 5)(x - 3)$"},{"key":"D","text":"$(x + 5)(3x - 1)$"}]$lyceon_json$::jsonb, 'A', NULL, E'First, factor out $3$ from $3x^2 + 12x - 15$ to get $3(x^2 + 4x - 5)$. Then factor the quadratic: two numbers that multiply to $-5$ and add to $4$ are $5$ and $-1$, giving $3(x + 5)(x - 1)$. The option $3(x - 5)(x + 1)$ results from a sign error, using factors $-5$ and $+1$ which multiply to $-5$ but add to $-4$, not $4$. The option $(3x + 5)(x - 3)$ expands to $3x^2 - 9x + 5x - 15 = 3x^2 - 4x - 15$, which does not match the original, reflecting an incorrect factoring setup. The option $(x + 5)(3x - 1)$ expands to $3x^2 - x + 15x - 5 = 3x^2 + 14x - 5$, an arithmetic slip from failing to properly extract the common factor of $3$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2A9D9KD', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 2, 'mcq', E'$4x - 3y = 11$
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2CBUQN9', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 2, 'mcq', E'In triangle $PQR$, the measure of angle $P$ is $47^\\circ$ and the exterior angle at vertex $R$ measures $119^\\circ$. What is the measure, in degrees, of angle $Q$?', NULL, $lyceon_json$[{"key":"A","text":"$14^\\circ$"},{"key":"B","text":"$61^\\circ$"},{"key":"C","text":"$72^\\circ$"},{"key":"D","text":"$133^\\circ$"}]$lyceon_json$::jsonb, 'C', NULL, E'The exterior angle at vertex $R$ equals the sum of the two non-adjacent interior angles: $\\angle P + \\angle Q = 119^\\circ$. Since $\\angle P = 47^\\circ$, we get $\\angle Q = 119 - 47 = 72^\\circ$. The value $14^\\circ$ comes from subtracting $47$ from the interior angle at $R$ ($61 - 47 = 14$), setting up the wrong equation. The value $61^\\circ$ is the interior angle at $R$ ($180 - 119 = 61$), which confuses the interior angle at $R$ with the requested angle $Q$. The value $133^\\circ$ comes from computing $180 - 47 = 133$, subtracting only angle $P$ from $180$ instead of using the exterior angle theorem.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2CYFBCW', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 2, 'mcq', E'A right circular cylinder has a diameter of $10$ centimeters and a height of $23$ centimeters. What is the volume, in cubic centimeters, of the cylinder?', NULL, $lyceon_json$[{"key":"A","text":"$230\\pi$"},{"key":"B","text":"$575\\pi$"},{"key":"C","text":"$1150\\pi$"},{"key":"D","text":"$2300\\pi$"}]$lyceon_json$::jsonb, 'B', NULL, E'The radius is $\\frac{10}{2} = 5$ cm. The volume of a cylinder is $V = \\pi r^2 h = \\pi(5)^2(23) = 575\\pi$ cubic centimeters. The value $230\\pi$ uses the formula $\\pi \\cdot d \\cdot h = \\pi(10)(23)$, treating the diameter as though it replaces $r^2$ and omitting the squaring step. The value $1150\\pi$ doubles the correct answer, perhaps from erroneously including a factor of $2$ as in a lateral surface area formula. The value $2300\\pi$ uses the diameter instead of the radius in the squared term: $\\pi(10)^2(23) = 2300\\pi$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2DLAVA5', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 3, 'mcq', E'What is the solution to the equation $\\frac{2(3x - 4)}{5} - \\frac{x + 3}{2} = \\frac{x}{10}$?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{31}{6}$"},{"key":"B","text":"$\\frac{31}{7}$"},{"key":"C","text":"$\\frac{1}{6}$"},{"key":"D","text":"$\\frac{31}{8}$"}]$lyceon_json$::jsonb, 'A', NULL, E'Multiply every term by 10 (the LCD of 5, 2, and 10): $4(3x - 4) - 5(x + 3) = x$. Expanding: $12x - 16 - 5x - 15 = x$, so $7x - 31 = x$, then $6x = 31$, and $x = \\frac{31}{6}$. The value $\\frac{31}{7}$ results from correctly clearing denominators and expanding but neglecting to subtract $x$ from both sides, solving $7x = 31$ instead of $6x = 31$. The value $\\frac{1}{6}$ comes from a sign error when distributing the negative across $(x + 3)$: computing $-5x + 15$ instead of $-5x - 15$ yields $7x - 1 = x$, so $6x = 1$. The value $\\frac{31}{8}$ results from moving $x$ to the left side by adding rather than subtracting, obtaining $7x + x = 31$, so $8x = 31$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2EAYCKW', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 2, 'mcq', E'A data set consists of the values $14$, $17$, $19$, $22$, $22$, $25$, $29$, $33$, and $41$. If the value $41$ is removed from the data set, which of the following statements is true?', NULL, $lyceon_json$[{"key":"A","text":"The mean decreases and the median stays the same."},{"key":"B","text":"The mean decreases and the median increases."},{"key":"C","text":"The mean stays the same and the median decreases."},{"key":"D","text":"Both the mean and the median decrease."}]$lyceon_json$::jsonb, 'A', NULL, E'Original data (9 values): sum $= 222$, mean $= \\frac{222}{9} \\approx 24.67$. The median is the $5$th value $= 22$. After removing $41$ (8 values): sum $= 181$, mean $= \\frac{181}{8} = 22.625$, which is lower. The new median is the average of the $4$th and $5$th values: $\\frac{22 + 22}{2} = 22$, unchanged. So the mean decreases while the median stays the same. The claim that the median increases is wrong because the two middle values are both $22$. The claim that the mean stays the same is wrong because removing the largest value lowers the average. The claim that both decrease is wrong because the median remains $22$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2EZ1ALZ', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 1, 'mcq', E'The function $g$ is defined by $g(x) = 2x^2 - 3$. What is the value of $g(-3)$?', NULL, $lyceon_json$[{"key":"A","text":"$15$"},{"key":"B","text":"$-21$"},{"key":"C","text":"$21$"},{"key":"D","text":"$-15$"}]$lyceon_json$::jsonb, 'A', NULL, E'Substitute $x = -3$ into $g(x) = 2x^2 - 3$: $g(-3) = 2(-3)^2 - 3 = 2(9) - 3 = 18 - 3 = 15$. The value $-21$ results from incorrectly computing $(-3)^2 = -9$ instead of $9$, giving $2(-9) - 3 = -21$. The value $21$ comes from an arithmetic slip of adding $3$ instead of subtracting it: $2(9) + 3 = 21$. The value $-15$ results from both squaring the input incorrectly as $-9$ and mishandling the constant, reflecting a conceptual gap about how squaring affects negative numbers.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2FCOZF5', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 2, 'mcq', E'A store increases the price of a television by $20\\%$, and then offers a $20\\%$ discount on the new price. If the original price of the television was $650$ dollars, what is the final price, in dollars?', NULL, $lyceon_json$[{"key":"A","text":"$520.00$"},{"key":"B","text":"$624.00$"},{"key":"C","text":"$650.00$"},{"key":"D","text":"$676.00$"}]$lyceon_json$::jsonb, 'B', NULL, E'After a $20\\%$ increase, the price is $650 \\times 1.20 = 780$ dollars. After a $20\\%$ discount on $780$: $780 \\times 0.80 = 624$ dollars. The value $520$ comes from applying only the discount without the increase ($650 \\times 0.80 = 520$). The value $650$ reflects the misconception that a $20\\%$ increase followed by a $20\\%$ decrease returns to the original price. The value $676$ comes from an arithmetic error such as computing $650 \\times 1.04 = 676$, treating the net effect as $4\\%$ by adding the percentages.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2FHWLYP', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 3, 'mcq', E'The function $p$ is defined by $p(x) = 3 \\cdot 2^x$. If $p(a + 4) = k \\cdot p(a)$ for all values of $a$, what is the value of $k$?', NULL, $lyceon_json$[{"key":"A","text":"$16$"},{"key":"B","text":"$8$"},{"key":"C","text":"$12$"},{"key":"D","text":"$4$"}]$lyceon_json$::jsonb, 'A', NULL, E'Compute $p(a + 4) = 3 \\cdot 2^{a+4} = 3 \\cdot 2^a \\cdot 2^4 = 16 \\cdot (3 \\cdot 2^a) = 16 \\cdot p(a)$. Therefore $k = 16$. The value $8$ comes from an arithmetic slip of computing $2^4 = 8$ instead of $16$, confusing it with $2^3$. The value $12$ results from an incorrect setup that treats the coefficient $3$ and the shift $4$ as additive components, such as computing $3 \\cdot 4 = 12$. The value $4$ reflects a conceptual gap about exponential growth, mistakenly believing that increasing the exponent by $4$ multiplies the output by $4$ rather than by $2^4$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2FWPQMR', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 2, 'mcq', E'How many distinct real solutions does the equation $2x^2 + 7x + 9 = 0$ have?', NULL, $lyceon_json$[{"key":"A","text":"$0$"},{"key":"B","text":"$1$"},{"key":"C","text":"$2$"},{"key":"D","text":"$3$"}]$lyceon_json$::jsonb, 'A', NULL, E'Use the discriminant $\\Delta = b^2 - 4ac$ with $a = 2$, $b = 7$, and $c = 9$: $\\Delta = 49 - 72 = -23$. Since the discriminant is negative, the equation has no distinct real solutions. The answer $1$ reflects confusion between a negative discriminant and a zero discriminant, as only a zero discriminant yields exactly one repeated real solution. The answer $2$ comes from assuming every quadratic equation has two real solutions without checking the discriminant. The answer $3$ reflects a fundamental misunderstanding, since a quadratic equation can have at most $2$ solutions.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2H26UEA', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 1, 'mcq', E'A line of best fit for a scatterplot is given by $y = 3.7x + 14$. According to this model, what is the predicted value of $y$ when $x = 8$?', NULL, $lyceon_json$[{"key":"A","text":"$43.6$"},{"key":"B","text":"$29.6$"},{"key":"C","text":"$44.6$"},{"key":"D","text":"$51.6$"}]$lyceon_json$::jsonb, 'A', NULL, E'Substituting $x = 8$: $y = 3.7(8) + 14 = 29.6 + 14 = 43.6$. The value $29.6$ comes from computing $3.7 \\times 8$ but forgetting to add the intercept of 14. The value $44.6$ results from a multiplication error, computing $3.7 \\times 8 = 30.6$ instead of $29.6$. The value $51.6$ comes from incorrectly computing $3.7 \\times 8 = 37.6$ and then adding 14.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 40, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2HA7CLU', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 1, 'mcq', E'In a right triangle, the two legs have lengths $\\sqrt{11}$ and $\\sqrt{14}$. What is the length of the hypotenuse?', NULL, $lyceon_json$[{"key":"A","text":"$\\sqrt{3}$"},{"key":"B","text":"$5$"},{"key":"C","text":"$\\sqrt{154}$"},{"key":"D","text":"$25$"}]$lyceon_json$::jsonb, 'B', NULL, E'By the Pythagorean theorem, $c^2 = (\\sqrt{11})^2 + (\\sqrt{14})^2 = 11 + 14 = 25$, so $c = \\sqrt{25} = 5$. The value $\\sqrt{3}$ results from subtracting the squares ($14 - 11 = 3$) instead of adding them, setting up the equation incorrectly. The value $\\sqrt{154}$ comes from multiplying $11 \\times 14 = 154$ under the radical, confusing the Pythagorean theorem with multiplication. The value $25$ is $c^2$ before taking the square root, stopping one step short of the final answer.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2HEFPFX', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 1, 'mcq', E'A random sample of $250$ voters in a city found that $54\\%$ support a proposed parks initiative, with a margin of error of $4\\%$. Which of the following is the best interpretation of this result?', NULL, $lyceon_json$[{"key":"A","text":"Exactly $54\\%$ of all voters in the city support the parks initiative."},{"key":"B","text":"Between $50\\%$ and $58\\%$ of all voters in the city are likely to support the parks initiative."},{"key":"C","text":"Between $50\\%$ and $58\\%$ of the $250$ sampled voters support the parks initiative."},{"key":"D","text":"The survey result would change by $4\\%$ if the sample size were increased."}]$lyceon_json$::jsonb, 'B', NULL, E'A margin of error of $4\\%$ around a sample proportion of $54\\%$ means the plausible range for the true population proportion is $54\\% - 4\\% = 50\\%$ to $54\\% + 4\\% = 58\\%$. The claim that exactly $54\\%$ of all voters support it ignores sampling variability. The statement applying the interval to the sampled voters confuses the sample statistic with the population parameter — the sample result is already known exactly. The claim about results changing by $4\\%$ with a larger sample misunderstands what margin of error represents.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 50, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2HN6ISP', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 2, 'mcq', E'Which expression is equivalent to $\\frac{9x^2 - 16}{3x + 4}$ for all values of $x$ where the expression is defined?', NULL, $lyceon_json$[{"key":"A","text":"$3x + 4$"},{"key":"B","text":"$3x - 4$"},{"key":"C","text":"$9x - 4$"},{"key":"D","text":"$9x + 16$"}]$lyceon_json$::jsonb, 'B', NULL, E'The numerator is a difference of squares: $9x^2 - 16 = (3x + 4)(3x - 4)$. Dividing by $(3x + 4)$ gives $3x - 4$. The value $3x + 4$ results from a sign error when factoring the difference of squares. The value $9x - 4$ incorrectly factors without taking the square root of $9x^2$. The value $9x + 16$ confuses the factoring pattern entirely.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2I4R92D', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 3, 'grid_in', E'A solid is composed of a right circular cylinder with a hemisphere attached to one end. The cylinder has a radius of $6$ centimeters and a height of $11$ centimeters. What is the total volume of the solid, in cubic centimeters? (Express your answer as a numerical coefficient of $\\pi$; enter only the coefficient.)', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '540', ARRAY['540'], E'The volume of the cylinder is $V_{\\text{cyl}} = \\pi r^2 h = \\pi(6)^2(11) = 396\\pi$ cubic centimeters. The volume of the hemisphere is $V_{\\text{hemi}} = \\frac{2}{3}\\pi r^3 = \\frac{2}{3}\\pi(6)^3 = \\frac{2}{3}\\pi(216) = 144\\pi$ cubic centimeters. The total volume is $396\\pi + 144\\pi = 540\\pi$. The numerical coefficient is $540$. Common errors include using the full sphere formula ($\\frac{4}{3}\\pi r^3 = 288\\pi$) instead of the hemisphere formula, which would give $396 + 288 = 684$, or forgetting to add the hemisphere volume entirely.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2IG475Z', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 2, 'mcq', E'A class of $31$ students was surveyed about whether they play a sport or a musical instrument. Of these students, $13$ play a sport, $9$ play a musical instrument, and $4$ play both. If a student is chosen at random from those who play a sport, what is the probability that the student also plays a musical instrument?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{4}{31}$"},{"key":"B","text":"$\\frac{4}{13}$"},{"key":"C","text":"$\\frac{4}{9}$"},{"key":"D","text":"$\\frac{9}{13}$"}]$lyceon_json$::jsonb, 'B', NULL, E'This is a conditional probability question. Given that the student plays a sport, the sample space is the $13$ sport-playing students. Of these, $4$ also play a musical instrument. The conditional probability is $\\frac{4}{13}$. The distractor $\\frac{4}{31}$ divides by the total class size instead of conditioning on sport players. The distractor $\\frac{4}{9}$ incorrectly conditions on musical instrument players rather than sport players. The distractor $\\frac{9}{13}$ uses the total number of instrument players in the numerator rather than only those who play both.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2JE06DB', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 1, 'mcq', E'The ages of $7$ participants in a workshop are $23$, $27$, $31$, $31$, $34$, $38$, and $41$. What is the median age of the participants?', NULL, $lyceon_json$[{"key":"A","text":"$27$"},{"key":"B","text":"$31$"},{"key":"C","text":"$32.5$"},{"key":"D","text":"$34$"}]$lyceon_json$::jsonb, 'B', NULL, E'With $7$ values in ascending order, the median is the $4$th value, which is $31$. The value $27$ results from selecting the wrong position, confusing the second value with the median. The value $32.5$ comes from averaging the $4$th and $5$th values ($31$ and $34$), as one would for an even-sized data set, but there are $7$ values so the median is the single middle value. The value $34$ comes from selecting the $5$th value instead of the $4$th.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 40, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2JSXXTR', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 2, 'mcq', E'The function $f$ is defined by $f(x) = (x - 7)^2 + 4$. What is the minimum value of $f(x)$?', NULL, $lyceon_json$[{"key":"A","text":"$4$"},{"key":"B","text":"$7$"},{"key":"C","text":"$-7$"},{"key":"D","text":"$-4$"}]$lyceon_json$::jsonb, 'A', NULL, E'The function $f(x) = (x - 7)^2 + 4$ is in vertex form $a(x - h)^2 + k$ with vertex at $(7, 4)$. Since $a = 1 > 0$, the parabola opens upward and the minimum value is the $y$-coordinate of the vertex, which is $4$. The value $7$ is the $x$-coordinate of the vertex, not the minimum output of the function, reflecting a misread of what the question asks. The value $-7$ comes from a sign error, incorrectly extracting $h = -7$ from the expression $(x - 7)$. The value $-4$ results from incorrectly negating the vertical shift $k = 4$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2K2C5RN', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 2, 'grid_in', E'A bookstore charges 7 dollars for each journal and a flat shipping fee of 11 dollars per order. A customer has a budget of at most 67 dollars. What is the maximum number of journals the customer can order?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '8', ARRAY['8'], E'The total cost for $j$ journals is $7j + 11$. Setting up the inequality $7j + 11 \\leq 67$ and subtracting 11 from both sides gives $7j \\leq 56$. Dividing both sides by 7 yields $j \\leq 8$. Since the number of journals must be a whole number, the maximum is 8.', NULL, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2L6EZT8', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 1, 'mcq', E'A circle has a radius of $17$ units. What is the area, in square units, of the circle?', NULL, $lyceon_json$[{"key":"A","text":"$34\\pi$"},{"key":"B","text":"$17\\pi$"},{"key":"C","text":"$289\\pi$"},{"key":"D","text":"$578\\pi$"}]$lyceon_json$::jsonb, 'C', NULL, E'The area of a circle is $A = \\pi r^2 = \\pi(17)^2 = 289\\pi$ square units. The value $34\\pi$ uses the diameter formula $2\\pi r$ instead of squaring the radius. The value $17\\pi$ uses the radius without squaring, computing $\\pi r$ instead of $\\pi r^2$. The value $578\\pi$ doubles the correct area, confusing area with another formula.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2L8KJZY', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 3, 'grid_in', E'The solution set of $-2(ax + 3) \\geq 4x - 7$ is $x \\leq \\frac{1}{8}$. What is the value of $a$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '2', ARRAY['2'], E'Distributing gives $-2ax - 6 \\geq 4x - 7$. Collecting the $x$ terms on the left and constants on the right yields $(-2a - 4)x \\geq -1$. For the solution to be $x \\leq \\frac{1}{8}$, the coefficient $-2a - 4$ must be negative (so dividing reverses the inequality), giving $x \\leq \\frac{-1}{-2a - 4} = \\frac{1}{2a + 4}$. Setting $\\frac{1}{2a + 4} = \\frac{1}{8}$ gives $2a + 4 = 8$, so $a = 2$. Verification: $-2(2x + 3) \\geq 4x - 7$ simplifies to $-4x - 6 \\geq 4x - 7$, which gives $1 \\geq 8x$, or $x \\leq \\frac{1}{8}$.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2LBGI01', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 3, 'grid_in', E'In triangle $ABC$, point $D$ lies on side $\\overline{BC}$ such that $\\overline{AD}$ bisects angle $A$. The measure of angle $B$ is $38^\\circ$ and the measure of angle $C$ is $74^\\circ$. What is the measure, in degrees, of angle $ADC$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '72', ARRAY['72'], E'First, find angle $A$: $180 - 38 - 74 = 68^\\circ$. Since $\\overline{AD}$ bisects angle $A$, each half measures $34^\\circ$. In triangle $ABD$, the angles are $\\angle BAD = 34^\\circ$, $\\angle ABD = 38^\\circ$, and $\\angle ADB = 180 - 34 - 38 = 108^\\circ$. Since angles $\\angle ADB$ and $\\angle ADC$ are supplementary (they form a straight line along $\\overline{BC}$), $\\angle ADC = 180 - 108 = 72^\\circ$. This can be verified in triangle $ADC$: $\\angle DAC + \\angle ACD + \\angle ADC = 34 + 74 + 72 = 180^\\circ$.', NULL, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2LMFPU1', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 3, 'mcq', E'If $a = \\frac{3x - 7}{x^2 - 4}$ and $b = \\frac{2}{x + 2}$, which expression is equivalent to $a - b$ for all values of $x$ where the expression is defined?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{x - 3}{x^2 - 4}$"},{"key":"B","text":"$\\frac{3x - 9}{x^2 - 4}$"},{"key":"C","text":"$\\frac{x - 11}{x^2 - 4}$"},{"key":"D","text":"$\\frac{3x - 5}{x^2 - 4}$"}]$lyceon_json$::jsonb, 'A', NULL, E'Since $x^2 - 4 = (x + 2)(x - 2)$, rewrite $b$ with the common denominator: $b = \\frac{2}{x + 2} = \\frac{2(x - 2)}{x^2 - 4} = \\frac{2x - 4}{x^2 - 4}$. Then $a - b = \\frac{3x - 7 - (2x - 4)}{x^2 - 4} = \\frac{3x - 7 - 2x + 4}{x^2 - 4} = \\frac{x - 3}{x^2 - 4}$. The option $\\frac{3x - 9}{x^2 - 4}$ results from an arithmetic slip of not multiplying $b$ by the correct factor, instead subtracting only the constant $2$ from the numerator to get $3x - 7 - 2 = 3x - 9$. The option $\\frac{x - 11}{x^2 - 4}$ comes from a sign error in distributing the negative, computing $-7 - 4 = -11$ instead of $-7 + 4 = -3$. The option $\\frac{3x - 5}{x^2 - 4}$ results from an incorrect setup where the $2x$ term is dropped, computing only $-7 - (-4) + 2$ to arrive at $-5$ while keeping the $3x$ coefficient.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2MFRQK8', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 3, 'mcq', E'A scatterplot shows the relationship between the age of a car, $x$, in years, and its resale value, $y$, in thousands of dollars. An exponential model for the data is $y = 31.4(0.83)^x$. According to this model, by what percent does the resale value decrease each year?', NULL, $lyceon_json$[{"key":"A","text":"$0.83\\%$"},{"key":"B","text":"$17\\%$"},{"key":"C","text":"$31.4\\%$"},{"key":"D","text":"$83\\%$"}]$lyceon_json$::jsonb, 'B', NULL, E'In the model $y = 31.4(0.83)^x$, the base $0.83$ means the value retains $83\\%$ of the previous year''s value each year. The annual decrease is $1 - 0.83 = 0.17$, or $17\\%$. The value $0.83\\%$ confuses the decay factor $0.83$ with the percentage decrease. The value $31.4\\%$ confuses the initial value coefficient with the rate of decrease. The value $83\\%$ mistakes the retention rate for the decrease rate, failing to subtract from $100\\%$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2MKGU3I', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 3, 'grid_in', E'A teacher records quiz scores for $11$ students: $52$, $58$, $63$, $67$, $71$, $73$, $73$, $79$, $84$, $88$, $94$. The teacher decides to add $4$ points to every score. What is the interquartile range of the adjusted scores?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '21', ARRAY['21'], E'Adding a constant to every value shifts the distribution but does not change measures of spread. The original sorted data has $11$ values, so the median is the $6$th value ($73$). The lower half is the first $5$ values: $52, 58, 63, 67, 71$, and $Q_1$ is the middle value $= 63$. The upper half is the last $5$ values: $73, 79, 84, 88, 94$, and $Q_3$ is the middle value $= 84$. The IQR $= 84 - 63 = 21$. After adding $4$ to every score, $Q_1 = 67$ and $Q_3 = 88$, so IQR $= 88 - 67 = 21$, unchanged. A common error is computing the range ($98 - 56 = 42$) instead of the IQR. Another error is thinking the addition of $4$ changes the IQR to $25$.', NULL, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2NGD7WE', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 2, 'mcq', E'A researcher collects data on the number of hours studied ($x$) and test scores ($y$) for $12$ students. The line of best fit is $y = 4.7x + 53$. One student studied for $6$ hours and scored $82$ on the test. What is the residual for this student''s data point?', NULL, $lyceon_json$[{"key":"A","text":"$-0.8$"},{"key":"B","text":"$0.8$"},{"key":"C","text":"$81.2$"},{"key":"D","text":"$110.2$"}]$lyceon_json$::jsonb, 'B', NULL, E'The predicted value is $y = 4.7(6) + 53 = 28.2 + 53 = 81.2$. The residual is actual minus predicted: $82 - 81.2 = 0.8$. The value $-0.8$ results from computing predicted minus actual instead of actual minus predicted, a sign error. The value $81.2$ is the predicted value itself, reflecting incomplete work that stops before computing the residual. The value $110.2$ comes from adding the actual score and the slope term ($82 + 28.2$) instead of subtracting, confusing the residual formula.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 70, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2NV4XAK', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 1, 'mcq', E'A jacket originally priced at $135$ dollars is on sale for $27\\%$ off. What is the sale price, in dollars?', NULL, $lyceon_json$[{"key":"A","text":"$36.45$"},{"key":"B","text":"$98.55$"},{"key":"C","text":"$108.00$"},{"key":"D","text":"$162.45$"}]$lyceon_json$::jsonb, 'B', NULL, E'The discount is $0.27 \\times 135 = 36.45$ dollars. The sale price is $135 - 36.45 = 98.55$ dollars. The value $36.45$ is the discount amount itself, not the sale price, reflecting incomplete reasoning. The value $108.00$ results from subtracting $27$ directly from $135$ instead of computing $27\\%$ of $135$. The value $162.45$ results from adding the discount to the original price instead of subtracting it.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2P6PZ8V', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 3, 'mcq', E'A system of equations is given: $$y = x^2 - 5x + 12$$ $$y = 3x + k$$ For what value of $k$ does this system have exactly one real solution?', NULL, $lyceon_json$[{"key":"A","text":"$-4$"},{"key":"B","text":"$4$"},{"key":"C","text":"$-12$"},{"key":"D","text":"$12$"}]$lyceon_json$::jsonb, 'A', NULL, E'Set the two expressions equal: $x^2 - 5x + 12 = 3x + k$, which simplifies to $x^2 - 8x + (12 - k) = 0$. For exactly one real solution, the discriminant must equal zero: $(-8)^2 - 4(1)(12 - k) = 0$, so $64 - 48 + 4k = 0$, giving $16 + 4k = 0$, thus $k = -4$. The value $4$ results from a sign error when solving $16 + 4k = 0$, incorrectly dividing to get a positive result. The value $-12$ comes from an arithmetic slip in computing the discriminant, such as miscomputing $4 \\cdot (12 - k)$ and arriving at $4k + 48 = 0$. The value $12$ results from setting the constant term $12 - k = 0$ directly, confusing the constant of the combined quadratic with the discriminant condition.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2QYXJBG', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 1, 'mcq', E'A jar contains $7$ red tokens, $11$ blue tokens, and $3$ yellow tokens. If one token is selected at random, what is the probability that it is blue?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{3}{21}$"},{"key":"B","text":"$\\frac{7}{21}$"},{"key":"C","text":"$\\frac{11}{21}$"},{"key":"D","text":"$\\frac{11}{18}$"}]$lyceon_json$::jsonb, 'C', NULL, E'The total number of tokens is $7 + 11 + 3 = 21$. The probability of selecting a blue token is the number of blue tokens divided by the total: $\\frac{11}{21}$. The distractor $\\frac{3}{21}$ results from using the count of yellow tokens instead of blue. The distractor $\\frac{7}{21}$ uses the count of red tokens instead of blue. The distractor $\\frac{11}{18}$ arises from forgetting to include the yellow tokens in the total, computing the denominator as $7 + 11 = 18$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2R8TBQJ', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 3, 'grid_in', E'$6x - 9y = 14$
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2RF0E35', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 1, 'mcq', E'A rectangle has a length of $17$ inches and a width of $11$ inches. What is the area of the rectangle, in square inches?', NULL, $lyceon_json$[{"key":"A","text":"$56$"},{"key":"B","text":"$143$"},{"key":"C","text":"$187$"},{"key":"D","text":"$286$"}]$lyceon_json$::jsonb, 'C', NULL, E'The area of a rectangle is $A = \\text{length} \\times \\text{width} = 17 \\times 11 = 187$ square inches. The value $56$ computes the perimeter $2(17 + 11) = 56$ instead of the area, confusing the two formulas. The value $143$ results from a multiplication error, such as computing $13 \\times 11$ instead of $17 \\times 11$. The value $286$ doubles the correct area, as though computing $2 \\times 17 \\times 11$, perhaps conflating the area formula with a surface area computation.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2T5MSGU', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 3, 'mcq', E'In the $xy$-plane, line $k$ has the equation $5x - 3y = 15$. Line $j$ is perpendicular to line $k$ and passes through the point $(7, 2)$. What is the $y$-intercept of line $j$?', NULL, $lyceon_json$[{"key":"A","text":"$-\\frac{29}{3}$"},{"key":"B","text":"$-\\frac{11}{5}$"},{"key":"C","text":"$\\frac{23}{5}$"},{"key":"D","text":"$\\frac{31}{5}$"}]$lyceon_json$::jsonb, 'D', NULL, E'Rewriting line $k$ in slope-intercept form: $5x - 3y = 15$ becomes $y = \\frac{5}{3}x - 5$, so line $k$ has slope $\\frac{5}{3}$. A line perpendicular to $k$ has slope equal to the negative reciprocal, which is $-\\frac{3}{5}$. Using point-slope form with $(7, 2)$: $y - 2 = -\\frac{3}{5}(x - 7)$. At $x = 0$: $y - 2 = -\\frac{3}{5}(-7) = \\frac{21}{5}$, so $y = 2 + \\frac{21}{5} = \\frac{10}{5} + \\frac{21}{5} = \\frac{31}{5}$. The value $-\\frac{29}{3}$ results from using the original slope $\\frac{5}{3}$ instead of the perpendicular slope, confusing parallel with perpendicular. The value $-\\frac{11}{5}$ comes from using slope $\\frac{3}{5}$ without the negative sign, yielding $y = 2 - \\frac{21}{5} = -\\frac{11}{5}$. The value $\\frac{23}{5}$ results from an arithmetic slip when adding $\\frac{21}{5} + 2$, incorrectly computing $\\frac{21 + 2}{5}$ instead of converting 2 to $\\frac{10}{5}$ first.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2THJUTG', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 3, 'grid_in', E'A sector of a circle has a central angle of $\\frac{2\\pi}{9}$ radians and an arc length of $14\\pi$ units. What is the area of the sector? (Express your answer as a numerical coefficient of $\\pi$; enter only the coefficient.)', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '441', ARRAY['441'], E'The arc length formula is $s = r\\theta$. Substituting: $14\\pi = r \\cdot \\frac{2\\pi}{9}$, so $r = \\frac{14\\pi \\cdot 9}{2\\pi} = 63$. The area of a sector is $A = \\frac{1}{2}r^2\\theta = \\frac{1}{2}(63)^2 \\cdot \\frac{2\\pi}{9} = \\frac{1}{2} \\cdot 3969 \\cdot \\frac{2\\pi}{9} = \\frac{3969\\pi}{9} = 441\\pi$. The numerical coefficient is $441$.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2UYAOJV', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 1, 'mcq', E'$7x + 2y = 41$
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2V2VMV0', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 3, 'mcq', E'A university researcher selects a random sample of $400$ first-year students from a large university and randomly assigns half to receive weekly peer tutoring sessions and half to a control group that receives no tutoring. After one semester, the tutored group has a statistically significantly higher average GPA. Which of the following is the most appropriate conclusion?', NULL, $lyceon_json$[{"key":"A","text":"Peer tutoring causes higher GPA among first-year students at this university."},{"key":"B","text":"Peer tutoring causes higher GPA among all college students nationwide."},{"key":"C","text":"Peer tutoring is associated with higher GPA, but causation cannot be established because students may have studied more on their own."},{"key":"D","text":"Peer tutoring causes higher GPA, but only among students who volunteered for the study."}]$lyceon_json$::jsonb, 'A', NULL, E'This study uses both random selection (from the university''s first-year students) and random assignment (to tutoring or control), so it supports both a causal conclusion and generalizability — but only to the population from which the sample was drawn, which is first-year students at this university. The claim about all college students nationwide extends beyond the sampled population. The statement that causation cannot be established is incorrect because random assignment controls for confounding variables such as independent study habits; the random assignment ensures these factors are balanced across groups on average. The claim that the conclusion applies only to volunteers is wrong because the participants were randomly selected, not self-selected volunteers.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2VQGS5X', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 1, 'grid_in', E'What is the positive solution to the equation $x^2 - 5x - 36 = 0$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '9', ARRAY['9'], E'Factoring: $x^2 - 5x - 36 = (x - 9)(x + 4) = 0$. The solutions are $x = 9$ and $x = -4$. The positive solution is $9$.', NULL, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2WBDNJH', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 1, 'mcq', E'Two parallel lines are cut by a transversal. One of the alternate interior angles measures $67°$. What is the measure, in degrees, of the other alternate interior angle?', NULL, $lyceon_json$[{"key":"A","text":"$67$"},{"key":"B","text":"$113$"},{"key":"C","text":"$23$"},{"key":"D","text":"$134$"}]$lyceon_json$::jsonb, 'A', NULL, E'Alternate interior angles formed by parallel lines and a transversal are congruent, so the other angle also measures $67°$. The value $113$ comes from computing the supplement $180 - 67 = 113$, confusing alternate interior angles with co-interior (same-side interior) angles. The value $23$ comes from subtracting $67$ from $90$, confusing the relationship with complementary angles. The value $134$ comes from doubling $67$, misapplying the angle relationship.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2WQ2RGT', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 2, 'mcq', E'A plumber charges a flat service fee plus an hourly rate for each job. For a job lasting 2 hours, the total charge is 189 dollars. For a job lasting 5 hours, the total charge is 339 dollars. What is the plumber''s hourly rate, in dollars?', NULL, $lyceon_json$[{"key":"A","text":"$30$"},{"key":"B","text":"$50$"},{"key":"C","text":"$75$"},{"key":"D","text":"$89$"}]$lyceon_json$::jsonb, 'B', NULL, E'Let the flat fee be $b$ and the hourly rate be $r$. Then $b + 2r = 189$ and $b + 5r = 339$. Subtracting the first equation from the second gives $3r = 150$, so $r = 50$. The hourly rate is 50 dollars. The value 30 comes from dividing the total difference of 150 by 5 (the hours from the larger job) instead of by 3 (the difference in hours), reflecting a misunderstanding of how to isolate the rate. The value 75 results from dividing 150 by 2 (the hours from the smaller job) instead of by the difference in hours, an error in setting up the elimination step. The value 89 is the flat fee ($b = 189 - 100 = 89$), which would be found by a student who correctly computes the rate but then reports the wrong quantity.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2X9Q0EK', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 3, 'grid_in', E'In right triangle $JKL$, the right angle is at $K$. If $\\sin(J) = \\frac{11}{61}$, what is the value of $\\cos(L)$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '11/61', ARRAY['11/61', '0.180', '.180'], E'In right triangle $JKL$ with the right angle at $K$, angles $J$ and $L$ are complementary, meaning $J + L = 90^\\circ$. By the co-function identity, $\\cos(L) = \\cos(90^\\circ - J) = \\sin(J)$. Therefore $\\cos(L) = \\frac{11}{61}$. A common error is to compute the third side using the Pythagorean theorem ($\\sqrt{61^2 - 11^2} = \\sqrt{3600} = 60$) and then use $\\cos(L) = \\frac{60}{61}$, which gives the cosine of angle $J$ rather than angle $L$.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2YS0QOH', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 3, 'mcq', E'Two independent random samples are taken from the same large population. Sample A has $150$ observations and produces a $95\\%$ confidence interval of $(0.41, 0.53)$ for the population proportion. Sample B has $600$ observations and produces a $95\\%$ confidence interval of $(0.44, 0.50)$. Which of the following statements is best supported by this information?', NULL, $lyceon_json$[{"key":"A","text":"Sample B's interval is more likely to contain the true population proportion than Sample A's interval."},{"key":"B","text":"The true population proportion is more likely to be $0.47$ than $0.45$."},{"key":"C","text":"Sample B's interval is narrower because a larger sample size reduces the margin of error."},{"key":"D","text":"If Sample B were repeated, it would always produce the interval $(0.44, 0.50)$."}]$lyceon_json$::jsonb, 'C', NULL, E'Both intervals are $95\\%$ confidence intervals, so they have the same confidence level. Sample B''s interval is narrower ($0.50 - 0.44 = 0.06$) than Sample A''s ($0.53 - 0.41 = 0.12$) because the margin of error decreases as the sample size increases (it is inversely proportional to $\\sqrt{n}$). The claim that Sample B''s interval is more likely to contain the true proportion is incorrect because both are $95\\%$ confidence intervals and share the same confidence level. The statement that $0.47$ is more likely than $0.45$ cannot be concluded from confidence intervals, which do not assign probabilities to specific values. The claim that repeating Sample B would always yield the same interval is false — each new sample produces a different interval due to sampling variability.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ZJUS8F', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 2, 'grid_in', E'What is the value of $x$ if $6x + 13 = 4x + 37$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '12', ARRAY['12'], E'Subtracting $4x$ from both sides: $2x + 13 = 37$. Subtracting 13: $2x = 24$. Dividing by 2: $x = 12$.', NULL, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ZSI93L', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 1, 'mcq', E'A school administrator notices that students who eat breakfast in the school cafeteria have higher average test scores than students who do not eat breakfast there. Which of the following best describes this study?', NULL, $lyceon_json$[{"key":"A","text":"An experiment, because the administrator compared two groups"},{"key":"B","text":"An observational study, because the administrator did not assign students to eat or not eat breakfast"},{"key":"C","text":"A survey, because the administrator collected test score data"},{"key":"D","text":"A census, because the administrator examined all students in the school"}]$lyceon_json$::jsonb, 'B', NULL, E'In this scenario, the administrator observed existing behavior (eating breakfast or not) and compared test scores without assigning students to groups. This is an observational study. It is not an experiment because no treatment was randomly assigned — simply comparing two groups does not make a study experimental. Calling it a survey is inaccurate because the administrator analyzed existing test score records rather than administering a questionnaire. It is not a census because there is no indication that every individual in the entire population was measured.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW206TKQL', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 3, 'mcq', E'Which choice can most reasonably be inferred from the text?', E'Economist Priya Narasimhan has analyzed municipal transit ridership data across 47 mid-sized North American cities from 2011 to 2023. She finds that cities which invested in dedicated bus rapid transit (BRT) corridors with signal priority and level boarding saw average ridership increases of 31% within five years of opening, while cities that instead added conventional bus routes over the same period experienced ridership declines averaging 8%. Notably, however, the three cities in her dataset that implemented BRT corridors but lacked signal priority—requiring buses to wait at standard traffic lights—saw ridership gains of only 4%, a figure Narasimhan describes as statistically indistinguishable from stagnation.', $lyceon_json$[{"key":"A","text":"Signal priority is likely a more important factor in BRT ridership gains than the provision of dedicated corridors alone."},{"key":"B","text":"Conventional bus routes are incapable of attracting new riders regardless of the level of investment they receive."},{"key":"C","text":"The 47 cities studied by Narasimhan are representative of transit ridership trends in all North American cities."},{"key":"D","text":"BRT systems with signal priority are less expensive to implement than conventional bus route expansions."}]$lyceon_json$::jsonb, 'A', NULL, E'The data show that full BRT with signal priority produced 31% ridership gains, while BRT corridors without signal priority produced only 4%—a negligible improvement. This contrast suggests that signal priority is a critical component of BRT''s effectiveness, not merely the dedicated corridor. The inference that signal priority is likely more important than dedicated corridors alone follows directly from this comparison. The option claiming conventional bus routes are incapable of attracting riders overgeneralizes; the passage reports average declines but does not rule out any possibility of gains under different conditions. The option about the 47 cities being representative of all North American cities introduces a claim about generalizability that the passage does not support—mid-sized cities may differ from large or small ones. The option about cost comparisons between BRT and conventional routes addresses a topic the passage never discusses.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW21ZONJ4', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 1, 'mcq', E'Which choice best states the main idea of the text?', E'Researchers at the University of Tromsø have documented a surprising behavior in Arctic reindeer: their eyes change color with the seasons. During the long summer days, the animals'' tapetum lucidum—a reflective layer behind the retina—appears golden. In winter darkness, however, it shifts to a deep blue. This color change alters how light is processed by the retina, increasing the animals'' sensitivity to the dim ultraviolet light that dominates the Arctic winter landscape. The adaptation allows reindeer to detect predators and forage for lichen even under conditions of near-total darkness.', $lyceon_json$[{"key":"A","text":"Arctic reindeer have a seasonal eye-color change that enhances their vision in winter darkness."},{"key":"B","text":"The tapetum lucidum is a reflective structure found in many Arctic mammals."},{"key":"C","text":"Ultraviolet light is the dominant form of light in the Arctic winter."},{"key":"D","text":"Reindeer in northern Norway forage for lichen during the darkest months of the year."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage centers on the discovery that Arctic reindeer undergo a seasonal change in eye color that improves their ability to see in winter darkness. The option stating that reindeer have a seasonal eye-color change enhancing winter vision captures this central idea. The option about the tapetum lucidum being found in many Arctic mammals introduces a claim not made in the passage, which discusses only reindeer. The option focusing on ultraviolet light''s dominance addresses a supporting detail rather than the main idea. The option about foraging for lichen likewise cites a specific detail mentioned as an outcome of the adaptation, not the passage''s central point.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW239V3XX', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 2, 'mcq', E'Which choice best describes the relationship between the two texts?', E'Text 1: Historian Luisa Ferreira argues that the decline of the Roman Republic was driven primarily by economic inequality. As wealth concentrated among senatorial elites through provincial exploitation, the dispossessed urban poor became a destabilizing political force. Ferreira contends that the Gracchi reforms failed not because of political overreach but because they could not reverse the structural entrenchment of elite wealth.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW24KWAIN', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'While the museum''s renovation required the temporary closure of several popular galleries on the third and fourth floors ______ curators organized a rotating series of exhibits in the building''s ground-level atrium so that visitors could still view highlights from the permanent collection during the fourteen-month construction period.', $lyceon_json$[{"key":"A","text":"floors, curators"},{"key":"B","text":"floors; curators"},{"key":"C","text":"floors. Curators"},{"key":"D","text":"floors; and curators"}]$lyceon_json$::jsonb, 'A', NULL, E'The clause beginning with "While" is a dependent (subordinate) clause, so it must be joined to the independent clause that follows with a comma. A semicolon after "floors" is incorrect because a semicolon requires independent clauses on both sides, and the "While" clause is dependent, making it a fragment if separated. A period after "floors" is similarly incorrect because it would strand the "While" clause as a sentence fragment. A semicolon paired with the coordinating conjunction "and" is incorrect both because a semicolon cannot follow a dependent clause and because the redundant conjunction creates a malformed join.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW27197OJ', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 1, 'mcq', E'Which choice most logically completes the text?', E'Ornithologists have long observed that European robins become unusually aggressive during the breeding season, attacking not only rival males but also inanimate objects that display a red breast patch. In controlled experiments, stuffed robin models with red breast feathers elicited fierce territorial responses, while models identical in size and shape but lacking the red patch were largely ignored. These findings suggest that the robins'' aggression is triggered primarily by ________', $lyceon_json$[{"key":"A","text":"the visual cue of the red breast patch rather than by the overall form of an intruder."},{"key":"B","text":"a learned response to previous encounters with territorial rivals during past breeding seasons."},{"key":"C","text":"the size and posture of potential intruders entering the robin's nesting territory."},{"key":"D","text":"hormonal changes that occur only in male robins at the onset of the breeding season."}]$lyceon_json$::jsonb, 'A', NULL, E'The experiments show that models with a red patch provoke aggression while identically shaped models without it do not, which logically leads to the conclusion that the red breast patch itself is the primary trigger. The completion about visual cue of the red patch rather than overall form follows directly from this evidence. The option about learned responses introduces a claim about learning that the passage does not support—the robins also attacked inanimate objects, suggesting an innate response to the visual stimulus. The option about size and posture contradicts the experimental finding that models of equal size and shape were ignored when they lacked the red patch. The option about hormonal changes in males goes beyond what the passage establishes—the passage does not discuss hormones or sex-specific differences.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW274NN1J', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 3, 'mcq', E'Based on the texts, how would the author of Text 1 most likely characterize the approach described in Text 2?', E'Text 1: Cognitive scientist Evelyn Matsuda argues that artificial intelligence systems trained on large language models do not possess genuine understanding. She contends that these systems operate through statistical pattern matching across vast corpora, producing outputs that mimic comprehension without any underlying semantic representation. Matsuda draws an analogy to a clerk who files documents by matching keywords on labels without ever reading the contents: the filing is systematic and often useful, but it does not constitute knowledge of what the documents contain.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW28QTVJ3', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'Sociologist Hakim Delacroix surveyed 1,340 bilingual professionals in Brussels and found that those who regularly code-switch between French and Dutch in workplace meetings reported higher cognitive flexibility scores on standardized assessments. Delacroix cautions, however, that participants who code-switch frequently may have self-selected into multilingual work environments precisely because they already possessed strong cognitive flexibility. _______ the observed correlation may not reflect a causal effect of code-switching on cognition.', $lyceon_json$[{"key":"A","text":"In addition,"},{"key":"B","text":"For example,"},{"key":"C","text":"In other words,"},{"key":"D","text":"On the contrary,"}]$lyceon_json$::jsonb, 'C', NULL, E'The sentence before the blank warns of a self-selection problem: participants may have already been cognitively flexible before they began code-switching. The sentence after the blank restates this caution in broader terms, concluding that the correlation may not be causal. "In other words," correctly signals that the final sentence is a restatement or clarification of the self-selection concern. "In addition," wrongly implies a new, independent point is being introduced, but the final sentence rephrases rather than extends the previous claim. "For example," wrongly treats the concluding statement as a specific illustration, when it is a general reformulation of the caution. "On the contrary," wrongly suggests the final sentence contradicts Delacroix''s caution, when it actually reinforces and restates it.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW29J9SJK', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 1, 'mcq', E'Based on the texts, how would the author of Text 2 most likely respond to the claim made in Text 1?', E'Text 1: Urban planner Desmond Okafor argues that cities should mandate green roofs on all new commercial buildings. He contends that green roofs reduce urban heat island effects, lower cooling costs, and manage stormwater runoff, making them an essential tool for sustainable urban development.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2B71N0Z', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 3, 'mcq', E'Which choice best describes the main idea of the text?', E'Historian Mariana Velasco has challenged the prevailing interpretation of the 1739 Stono Rebellion, the largest slave uprising in colonial British North America. Earlier scholars attributed the rebels'' march toward Spanish Florida to a straightforward desire for the freedom promised by Spanish colonial edicts. Velasco argues, however, that this reading underestimates the rebels'' political sophistication. Drawing on parish records from the Kingdom of Kongo and ship manifests from Charleston, she demonstrates that many of the rebellion''s leaders had served as soldiers or minor officials in the Kongolese civil wars of the 1710s and 1720s. Their march, Velasco contends, was not merely flight but a calculated military campaign informed by Central African traditions of organized resistance and negotiated sovereignty.', $lyceon_json$[{"key":"A","text":"Velasco reinterprets the Stono Rebellion as a politically sophisticated military campaign shaped by the leaders' Central African backgrounds, not simply a flight toward Spanish freedom."},{"key":"B","text":"The Stono Rebellion was the most consequential slave uprising in colonial North America because of its leaders' military experience."},{"key":"C","text":"Parish records from the Kingdom of Kongo reveal that the Stono rebels were primarily motivated by religious convictions rather than political strategy."},{"key":"D","text":"Velasco's research proves that Spanish colonial edicts had no influence on the rebels' decision to march southward."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes Velasco''s argument that the Stono Rebellion should be understood as a calculated military campaign drawing on Central African political and military traditions, rather than merely an escape toward Spanish-promised freedom. The option characterizing Velasco''s reinterpretation as emphasizing political sophistication and Central African backgrounds captures this central idea. The option calling it the most consequential uprising because of military experience introduces a comparative claim the passage never makes—it says ''largest,'' not ''most consequential,'' and does not argue that military experience was what made it significant. The option about religious convictions misrepresents the parish records, which the passage says Velasco used to establish the leaders'' roles as soldiers and officials, not their religious motivations. The option stating Velasco proves Spanish edicts had no influence overstates her argument; she contends the earlier reading underestimates sophistication, not that the edicts were irrelevant.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2BEPY08', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 2, 'mcq', E'Which choice best describes the overall structure of the text?', E'When the Pacific oyster was introduced to Willapa Bay in the 1920s, shellfish farmers celebrated: the species grew faster and tolerated wider temperature ranges than native Olympia oysters. However, the newcomer''s dominance soon produced unforeseen consequences. Pacific oysters outcompeted native species for substrate, altered sediment composition, and disrupted the habitat of eelgrass beds essential to juvenile salmon. Today, restoration ecologists are attempting to reintroduce Olympia oysters, but the entrenched Pacific populations resist displacement.', $lyceon_json$[{"key":"A","text":"It presents an initially positive development, then describes its negative consequences, and concludes with a current effort to address the problem."},{"key":"B","text":"It compares two competing scientific theories about shellfish ecology and evaluates the evidence supporting each."},{"key":"C","text":"It describes a historical event, argues that its importance has been exaggerated, and proposes a reinterpretation."},{"key":"D","text":"It introduces an ecological concept, provides a series of examples illustrating the concept, and then defines its key terms."}]$lyceon_json$::jsonb, 'A', NULL, E'The text begins with farmers celebrating the Pacific oyster''s advantages (positive development), transitions with "However" to describe ecological harms (negative consequences), and ends with restoration efforts (current attempt to address the problem). This three-part structure matches the choice describing an initially positive development followed by negative consequences and a current corrective effort. The choice about competing scientific theories is wrong because the passage describes a historical sequence of events, not a debate between theories. The choice about arguing that the event''s importance has been exaggerated is wrong because the passage does not minimize the introduction''s significance—it emphasizes its substantial ecological damage. The choice about introducing an ecological concept and providing examples is wrong because the passage narrates a specific case rather than defining a general concept.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2CQUSIC', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The assertion by several prominent economists that the central bank''s decision to lower interest rates during a period of historically low unemployment ______ would inevitably produce asset bubbles of the kind observed in the late 2000s has been challenged by a new study from the Riksbank, which found no statistically significant correlation between rate cuts and speculative excess in economies with robust regulatory frameworks.', $lyceon_json$[{"key":"A","text":"unemployment, would"},{"key":"B","text":"unemployment; would"},{"key":"C","text":"unemployment. Would"},{"key":"D","text":"unemployment would"}]$lyceon_json$::jsonb, 'D', NULL, E'The word "would" is the main verb of the noun clause introduced by "that" earlier in the sentence: "the assertion...that the central bank''s decision...would inevitably produce asset bubbles." No punctuation should interrupt this noun clause. A comma before "would" incorrectly separates the subject of the noun clause ("the central bank''s decision to lower interest rates during a period of historically low unemployment") from its verb. A semicolon before "would" would fracture the noun clause into two parts, neither of which can stand as an independent clause. A period before "Would" creates two fragments, severing the noun clause from both its introductory "that" and from the main verb "has been challenged."', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2DNMS15', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 3, 'mcq', E'Which finding, if true, would most directly undermine the explanation offered by the researchers?', E'Paleoclimatologists studying sediment cores from Lake Petén Itzá in Guatemala have proposed that a series of severe droughts between 800 and 1000 CE was the primary driver of the Classic Maya collapse. Their analysis of oxygen isotope ratios in fossilized ostracod shells reveals pronounced dry intervals coinciding with major periods of urban abandonment across the Maya lowlands. The researchers argue that these droughts destabilized agricultural systems dependent on seasonal rainfall, triggering cascading failures in food supply, trade networks, and political authority.', $lyceon_json$[{"key":"A","text":"Archaeological evidence shows that several Maya cities in the highlands, which relied on irrigation rather than rainfall, experienced population declines of similar magnitude during the same period."},{"key":"B","text":"Pollen records from the same sediment cores indicate a sharp decline in maize cultivation beginning around 810 CE."},{"key":"C","text":"Inscriptions at the site of Calakmul record a series of military defeats suffered by the city's ruling dynasty between 790 and 820 CE."},{"key":"D","text":"Ostracod-based isotope analysis has been validated as a reliable proxy for historical precipitation patterns in tropical lake environments."}]$lyceon_json$::jsonb, 'A', NULL, E'The researchers argue that droughts destabilized rainfall-dependent agricultural systems, causing the collapse. If highland cities that used irrigation—and thus would not have been affected by rainfall reduction—experienced similar population declines during the same period, this would undermine the claim that drought-driven agricultural failure was the primary cause, since the collapse occurred even where the proposed mechanism did not apply. The pollen records showing maize decline around 810 CE would actually support the drought explanation by showing agricultural impact consistent with the hypothesis. The military defeat inscriptions describe a possible contributing factor but do not challenge the specific mechanism of drought-driven agricultural collapse. The validation of ostracod isotope analysis as a reliable precipitation proxy would strengthen, not undermine, the researchers'' evidence base.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2DVEJDW', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Dr. Annika Lindqvist ______ a marine biologist who spent eleven years cataloging deep-sea hydrothermal vent ecosystems in the mid-Atlantic ridge, recently published findings suggesting that chemosynthetic bacteria thriving near the Mariana Trench may produce compounds with untapped pharmaceutical applications.', $lyceon_json$[{"key":"A","text":"Lindqvist; a"},{"key":"B","text":"Lindqvist, a"},{"key":"C","text":"Lindqvist. A"},{"key":"D","text":"Lindqvist: a"}]$lyceon_json$::jsonb, 'B', NULL, E'The phrase "a marine biologist who spent eleven years cataloging deep-sea hydrothermal vent ecosystems in the mid-Atlantic ridge" is a nonrestrictive appositive renaming Dr. Annika Lindqvist, so it must be set off by commas. A semicolon after the name is incorrect because a semicolon requires an independent clause on each side, and "a marine biologist who spent..." is a noun phrase, not an independent clause. A period after the name creates a sentence fragment ("Dr. Annika Lindqvist."). A colon after the name is incorrect because standard usage requires a colon to follow an independent clause, and the name alone is not one.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2FAANPT', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 2, 'mcq', E'Which choice completes the text with the most logical transition?', E'During the late Edo period, Japanese woodblock printmaker Utagawa Kuniyoshi gained fame for his dramatic warrior prints. _______ Kuniyoshi also produced an extensive series of prints depicting domestic cats in human-like poses, works that art historians now regard as pioneering examples of anthropomorphic satire in ukiyo-e.', $lyceon_json$[{"key":"A","text":"For instance,"},{"key":"B","text":"In other words,"},{"key":"C","text":"However,"},{"key":"D","text":"Subsequently,"}]$lyceon_json$::jsonb, 'C', NULL, E'The first sentence establishes Kuniyoshi''s fame for warrior prints, while the sentence after the blank introduces a contrasting aspect of his work: lighthearted cat prints. "However," correctly signals this unexpected contrast between the dramatic warrior imagery and the playful anthropomorphic cat series. "For instance," wrongly treats the cat prints as an example of warrior prints, but they are a different genre entirely. "In other words," wrongly implies the cat prints restate or paraphrase the warrior-print achievement, when they represent a separate body of work. "Subsequently," wrongly implies a chronological sequence, but the passage does not establish that the cat prints came after the warrior prints in time; it contrasts subject matter, not timeline.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2FD3RQG', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 2, 'mcq', E'Which choice best states the central claim of the text?', E'In the 1970s, ecologist Daniel Janzen proposed that tropical mountain passes act as stronger barriers to species dispersal than temperate ones. Because tropical organisms experience minimal seasonal temperature variation, he argued, they develop narrower thermal tolerances. A mountain pass that a temperate species—accustomed to wide temperature swings—might cross with little physiological stress could prove insurmountable for a tropical species adapted to a nearly constant 27°C. Recent physiological studies of 83 beetle species across elevational gradients in Borneo and Costa Rica have largely corroborated Janzen''s prediction, finding that tropical insects'' critical thermal maxima exceed their habitat temperatures by only 3–5°C, compared with 10–15°C for temperate counterparts.', $lyceon_json$[{"key":"A","text":"Tropical organisms' narrow thermal tolerances make mountain passes more effective barriers to their dispersal than to the dispersal of temperate organisms."},{"key":"B","text":"Daniel Janzen's research in the 1970s focused primarily on beetle species found in Borneo and Costa Rica."},{"key":"C","text":"Temperate species are better adapted to survive extreme environments than tropical species are."},{"key":"D","text":"Recent studies have overturned Janzen's hypothesis about the role of mountain passes in limiting species movement."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage presents Janzen''s hypothesis that tropical mountain passes are stronger dispersal barriers because tropical organisms have narrow thermal tolerances, and it notes that recent beetle studies have corroborated this idea. The option about narrow thermal tolerances making mountain passes more effective barriers for tropical organisms accurately captures this central claim. The option attributing beetle research in Borneo and Costa Rica to Janzen conflates his original hypothesis with later corroborating studies conducted by other researchers. The option claiming temperate species are better adapted to extreme environments overgeneralizes the passage''s specific point about thermal tolerance ranges near habitat temperatures into a sweeping survival claim. The option stating that recent studies overturned Janzen''s hypothesis directly contradicts the passage, which says the studies largely corroborated it.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2FLTW0K', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 1, 'mcq', E'Which choice completes the text with the most logical transition?', E'Geochemist Lara Okonkwo has demonstrated that volcanic glass from Iceland''s Hekla eruptions contains unusually high concentrations of fluorine. _______ her findings have prompted environmental agencies to reassess fluorine contamination thresholds for groundwater near active volcanic sites.', $lyceon_json$[{"key":"A","text":"Accordingly,"},{"key":"B","text":"Nevertheless,"},{"key":"C","text":"In contrast,"},{"key":"D","text":"Specifically,"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage states that Okonkwo demonstrated high fluorine concentrations in volcanic glass, and the sentence after the blank describes a consequence of those findings: environmental agencies reassessing contamination thresholds. The transition "Accordingly," correctly signals that the second statement follows as a logical result of the first. "Nevertheless," wrongly implies the reassessment happened despite the findings, introducing a concession where none exists. "In contrast," wrongly suggests an opposition between the findings and the reassessment, but they are causally linked. "Specifically," wrongly implies the second sentence narrows or elaborates on the first, when it actually describes a separate consequential action.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2FND0CK', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 2, 'mcq', E'Which choice most logically completes the text?', E'Linguist Ekaterina Rakhilina has documented a pattern she calls "semantic drift in closed-class morphemes" in several Uralic languages. She observes that locative case suffixes—grammatical markers originally indicating physical location—have gradually acquired abstract temporal and causal meanings. In Finnish, for instance, the inessive case suffix -ssa/-ssä, once restricted to meanings like ''inside a container,'' is now routinely used to express duration (''in three hours'') and psychological states (''in despair''). Rakhilina argues that this pattern arises because speakers routinely extend spatial metaphors to non-spatial domains, and over generations these metaphorical uses become conventionalized. If her analysis is correct, one would expect that ________', $lyceon_json$[{"key":"A","text":"languages unrelated to the Uralic family that also employ locative case morphology would show analogous extensions of spatial markers into temporal and abstract domains."},{"key":"B","text":"Uralic languages that lack locative case suffixes would nonetheless develop temporal expressions structurally identical to those in Finnish."},{"key":"C","text":"the original spatial meanings of locative suffixes in Finnish would have disappeared entirely by now, replaced by the newer abstract senses."},{"key":"D","text":"speakers of Finnish would be unable to distinguish between the spatial and temporal uses of the inessive suffix in everyday communication."}]$lyceon_json$::jsonb, 'A', NULL, E'Rakhilina''s analysis attributes semantic drift to a universal cognitive tendency—speakers extending spatial metaphors to non-spatial domains. If this mechanism is universal, one would expect it to operate in any language with locative morphology, not only Uralic ones. The option predicting analogous extensions in unrelated languages with locative case morphology follows logically from the universality of the proposed mechanism. The option about Uralic languages lacking locative suffixes developing identical temporal expressions is illogical because the mechanism requires existing spatial markers to undergo extension. The option claiming original spatial meanings would have disappeared overstates the process; conventionalization of new senses does not require loss of old ones, and the passage notes that -ssa/-ssä retains its spatial meaning alongside newer uses. The option about speakers being unable to distinguish uses is unsupported and implausible—conventionalized polysemy is a normal feature of language that speakers navigate routinely.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2I8MEYK', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Renowned for its high-altitude vineyards, the Cafayate Valley in northwestern Argentina produces Torrontés wines with distinctive floral aromas. To preserve these delicate aromatics during fermentation, ______ temperatures in the cellar to remain below fifteen degrees Celsius throughout the seventy-two-hour maceration period that the winemaking cooperative''s protocol mandates.', $lyceon_json$[{"key":"A","text":"the winemakers require"},{"key":"B","text":"it is required by winemakers that"},{"key":"C","text":"the requirement of winemakers is for"},{"key":"D","text":"requiring the winemakers to keep"}]$lyceon_json$::jsonb, 'A', NULL, E'The introductory infinitive phrase "To preserve these delicate aromatics during fermentation" expresses purpose and must be immediately followed by the noun performing that action. "The winemakers require" correctly places the agent (winemakers) as the subject, logically connecting them to the purpose of preserving aromatics. The passive construction "it is required by winemakers that" creates a dangling modifier because the impersonal pronoun "it" cannot logically be the agent preserving aromatics. The nominalization "the requirement of winemakers is for" similarly dangles the modifier by making "requirement" the grammatical subject rather than the agents performing the preservation. The participial phrase "requiring the winemakers to keep" eliminates the main clause verb entirely, leaving the sentence without a complete predicate.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2JXC8HV', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The Whitford Observatory, perched atop a granite ridge in central Vermont, has been tracking meteor showers since 1987. Each autumn, a team of eleven volunteer astronomers ______ the sky nightly from September through November, logging observations in a shared database maintained by the observatory''s longtime director.', $lyceon_json$[{"key":"A","text":"survey"},{"key":"B","text":"have surveyed"},{"key":"C","text":"surveys"},{"key":"D","text":"are surveying"}]$lyceon_json$::jsonb, 'C', NULL, E'The subject of the verb is "a team," which is a singular collective noun in American English and requires the singular verb form "surveys." The plural base form "survey" does not agree with the singular subject "a team." The present perfect "have surveyed" is plural and also shifts to a completed-action aspect that conflicts with the habitual present-tense context established by "each autumn" and "nightly." The present progressive "are surveying" is plural and implies an action in progress at a specific moment rather than a recurring seasonal habit.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2K9YT42', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 2, 'mcq', E'Which quotation from a literary critic, if accurate, would most directly support the claim presented in the text?', E'Some scholars of Victorian literature argue that Charlotte Brontë''s novel Villette (1853) represents a deliberate departure from the marriage-plot conventions that dominated mid-nineteenth-century British fiction. Unlike Jane Eyre, which concludes with the heroine''s union with Rochester, Villette ends ambiguously, leaving the fate of its protagonist Lucy Snowe''s romantic attachment unresolved. These scholars contend that Brontë used this ambiguity to critique the assumption that a woman''s narrative must culminate in marriage to achieve closure.', $lyceon_json$[{"key":"A","text":"\"Villette's refusal to deliver the expected matrimonial resolution functions as a structural argument against the ideological premises of the marriage plot itself.\""},{"key":"B","text":"\"Brontë's prose style in Villette is markedly more restrained than in Jane Eyre, reflecting the author's growing interest in realism over romanticism.\""},{"key":"C","text":"\"The character of Lucy Snowe is Brontë's most autobiographical creation, drawing heavily on the author's experiences teaching in Brussels.\""},{"key":"D","text":"\"Villette sold fewer copies than Jane Eyre in its first year of publication, suggesting that Victorian readers preferred conventional endings.\""}]$lyceon_json$::jsonb, 'A', NULL, E'The passage claims that Brontë used Villette''s ambiguous ending to critique the marriage-plot convention. The quotation describing Villette''s refusal to deliver a matrimonial resolution as a structural argument against the marriage plot directly supports this claim by echoing the idea that the novel''s ending is an intentional critique. The quotation about Brontë''s prose style and realism addresses a different aspect of the novel unrelated to the marriage-plot argument. The quotation about Lucy Snowe being autobiographical concerns the character''s origins, not the novel''s structural critique of narrative conventions. The quotation about sales figures addresses reader preferences, which is tangential—lower sales might suggest readers disliked the ending, but this does not support the specific claim that Brontë used ambiguity as deliberate critique.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2L7J9BT', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'Paleobotanist Mireia Cortez has argued that the high density of fossilized cycad pollen in Triassic rock strata from the Karoo Basin indicates a humid subtropical climate during that era. Other researchers have noted, though, that cycad pollen can be transported by wind over hundreds of kilometers. _______ the pollen concentration in a given stratum may reflect atmospheric dispersal patterns rather than local vegetation.', $lyceon_json$[{"key":"A","text":"Moreover,"},{"key":"B","text":"That is,"},{"key":"C","text":"Nonetheless,"},{"key":"D","text":"Meanwhile,"}]$lyceon_json$::jsonb, 'B', NULL, E'The sentence before the blank states that cycad pollen can travel vast distances by wind. The sentence after the blank restates this idea in more specific terms: pollen concentration may reflect dispersal patterns rather than local vegetation. Because the third sentence clarifies and rephrases the implication of the second, "That is," is the correct transition, signaling an explanatory restatement. "Moreover," wrongly suggests the third sentence adds a new, separate point rather than restating the preceding one. "Nonetheless," wrongly introduces a concession, implying the third sentence contradicts the wind-transport observation, when it actually elaborates on it. "Meanwhile," wrongly implies two simultaneous but unrelated events, but the third sentence directly follows from the second logically, not temporally.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2LKSP4L', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 3, 'mcq', E'Which choice best describes the function of the second paragraph in relation to the first?', E'Literary scholars have traditionally read Nella Larsen''s 1929 novel Passing as a meditation on racial identity in Jazz Age America. The protagonist Irene Redfield''s anxiety about her friend Clare Kendry''s decision to pass as white has been interpreted primarily through the lens of racial transgression and the precariousness of social categories.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2LRVF0R', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Neither the paleontologist''s exhaustive survey of Cretaceous-era fossilized pollen samples collected from seventeen distinct geological strata nor the geochemical analysis of sediment cores extracted from the Baranof formation ______ sufficient evidence to confirm the hypothesis that a prolonged volcanic winter triggered the mass extinction event documented in the stratigraphic record of the Tethys Sea basin.', $lyceon_json$[{"key":"A","text":"have yielded"},{"key":"B","text":"yield"},{"key":"C","text":"are yielding"},{"key":"D","text":"has yielded"}]$lyceon_json$::jsonb, 'D', NULL, E'With the correlative conjunction "neither...nor," the verb must agree in number with the nearer subject. The nearer subject is "the geochemical analysis," which is singular, so the singular "has yielded" is required. The plural "have yielded" incorrectly treats the compound subject as plural, violating the proximity-agreement rule for "neither...nor" constructions. The base plural form "yield" is likewise plural and also shifts to simple present tense, which does not match the completed-action context. The plural progressive "are yielding" fails on both number agreement and aspect, implying an ongoing action rather than a completed result.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2N0VT11', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 1, 'mcq', E'A student is writing a brief introduction about a community initiative for a local newsletter. The student wants to emphasize the scale of volunteer participation in the project. Which choice most effectively uses the relevant information from the notes to accomplish this goal?
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2PFKGAK', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 1, 'mcq', E'Which finding, if true, would most directly support the researchers'' hypothesis?', E'Marine biologists studying the unusual longevity of Greenland sharks—some individuals may exceed 400 years of age—have hypothesized that the sharks'' extremely slow metabolism is a primary factor in their extended lifespan. The researchers note that Greenland sharks inhabit waters averaging 1–3°C and grow at a rate of roughly one centimeter per year, far slower than most other shark species. They propose that this reduced metabolic rate limits the accumulation of cellular damage over time.', $lyceon_json$[{"key":"A","text":"Greenland shark cells cultured at 2°C show significantly lower rates of oxidative DNA damage than cells from a tropical shark species cultured at 26°C."},{"key":"B","text":"Greenland sharks have a more varied diet than previously believed, consuming both fish and marine mammals."},{"key":"C","text":"Other deep-sea shark species that inhabit cold water have been observed migrating to warmer waters during certain seasons."},{"key":"D","text":"Radiocarbon dating of Greenland shark eye lenses has confirmed that some individuals are over 390 years old."}]$lyceon_json$::jsonb, 'A', NULL, E'The researchers hypothesize that slow metabolism limits cellular damage, which extends lifespan. The finding that Greenland shark cells cultured at cold temperatures show lower oxidative DNA damage than tropical shark cells directly supports the proposed mechanism linking slow metabolism to reduced cellular damage. The finding about a varied diet is irrelevant to the metabolic-rate-and-cellular-damage hypothesis. The observation about other deep-sea sharks migrating to warmer waters neither supports nor undermines the specific claim about Greenland shark metabolism. The radiocarbon dating finding confirms the sharks'' age but does not address why they live so long, which is the hypothesis in question.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2PQ689F', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The Vásquez Glacier in southern Patagonia has retreated nearly two kilometers since comprehensive measurements began in 1953. Scientists who ______ the glacier''s rate of movement over the past decade report that the pace of retreat has accelerated sharply, with the most significant losses occurring during the austral summers of 2021 and 2023.', $lyceon_json$[{"key":"A","text":"had monitored"},{"key":"B","text":"are monitoring"},{"key":"C","text":"have monitored"},{"key":"D","text":"monitored"}]$lyceon_json$::jsonb, 'C', NULL, E'The present perfect "have monitored" correctly indicates an action that began in the past and continues to the present, which aligns with the time marker "over the past decade" and the present-tense main verb "report." The past perfect "had monitored" incorrectly implies the monitoring was completed before another past event, but the main clause verb "report" is in the present tense. The present progressive "are monitoring" suggests an action happening at this specific moment and does not capture the cumulative span of "the past decade." The simple past "monitored" implies the action is completed, conflicting with the ongoing nature conveyed by "over the past decade" paired with the present-tense "report."', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2QRZ5ZM', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 1, 'mcq', E'As used in the text, what does the word "settled" most nearly mean?', E'After decades of conflicting interpretations, the discovery of a well-preserved fossil in the Gobi Desert settled the long-standing debate among paleontologists about whether theropod dinosaurs possessed feathers. The specimen''s impressions were unmistakable, and even the most skeptical researchers accepted the finding.', $lyceon_json$[{"key":"A","text":"resolved"},{"key":"B","text":"colonized"},{"key":"C","text":"calmed"},{"key":"D","text":"deposited"}]$lyceon_json$::jsonb, 'A', NULL, E'In this passage, the fossil discovery brought the debate to a conclusion, so "settled" means brought to a definitive end. "Resolved" captures this meaning precisely. "Colonized" refers to establishing a settlement in a place, which is incoherent when applied to a debate. "Calmed" means to reduce agitation or emotional intensity, but the passage describes a factual dispute being concluded, not emotions being soothed. "Deposited" means to place or set down a physical object, which makes no sense when the subject is a debate.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2SDXRHS', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 2, 'mcq', E'As used in the text, what does the word "checks" most nearly mean?', E'In federalist political theory, the separation of governmental powers into distinct branches checks the accumulation of authority by any single entity. Without such structural constraints, theorists argued, even well-intentioned leaders would gradually concentrate decision-making power, undermining the republic''s foundational principles.', $lyceon_json$[{"key":"A","text":"restrains"},{"key":"B","text":"inspects"},{"key":"C","text":"marks"},{"key":"D","text":"verifies"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes how the separation of powers prevents any single entity from accumulating too much authority, so "checks" means holds back or limits. "Restrains" conveys this meaning of preventing excess. "Inspects" means to examine closely, but the passage is not about examining the accumulation—it is about preventing it. "Marks" means to make a visible sign or notation, which is nonsensical in the context of preventing authority accumulation. "Verifies" means to confirm accuracy, but the separation of powers is described as a constraint, not a confirmation mechanism.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2U0YJZK', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 3, 'mcq', E'A student is writing a research summary for a biology seminar. The student wants to highlight the unexpected nature of the researchers'' finding while accurately conveying the study''s methodology. Which choice most effectively uses the relevant information from the notes to accomplish this goal?
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2X1T341', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 3, 'mcq', E'As used in the text, what does the word "plastic" most nearly mean?', E'Neuroscientist Maryam Tehrani''s 2019 study demonstrated that the adult hippocampus remains remarkably plastic well into the seventh decade of life. Contrary to the long-held assumption that neural architecture becomes fixed after adolescence, Tehrani''s longitudinal imaging data showed robust dendritic branching in subjects who engaged in sustained spatial navigation tasks, suggesting that experiential demand continues to reshape neural circuitry throughout adulthood.', $lyceon_json$[{"key":"A","text":"adaptable"},{"key":"B","text":"synthetic"},{"key":"C","text":"decorative"},{"key":"D","text":"fragile"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage contrasts the assumption that the brain becomes fixed with evidence that neural circuitry continues to be reshaped by experience, so "plastic" means capable of being modified or reshaped. "Adaptable" captures this capacity for structural change. "Synthetic" refers to an artificially manufactured material, which is incoherent when describing a biological organ''s capacity for change. "Decorative" means serving an ornamental purpose, which has no logical connection to the brain''s ability to reorganize. "Fragile" means easily broken, which contradicts the passage''s emphasis on the hippocampus''s robust capacity for growth and restructuring.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2ZM1KWS', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 1, 'mcq', E'Which choice best describes the function of the underlined sentence in the text as a whole?', E'The volcanic island of Surtsey, which emerged from the North Atlantic in 1963, has served as an unparalleled natural laboratory for studying ecological colonization. Within four years, mosses and lichens had established themselves on the barren lava fields. _By 2009, researchers had cataloged over sixty vascular plant species on the island._ Scientists restrict human access to Surtsey to prevent contamination of its pristine ecological record.', $lyceon_json$[{"key":"A","text":"It provides a specific detail illustrating the progression of colonization on the island."},{"key":"B","text":"It introduces a new hypothesis about how plant species arrive on volcanic islands."},{"key":"C","text":"It challenges the claim that Surtsey's ecological record has remained uncontaminated."},{"key":"D","text":"It explains the methodology researchers used to survey plant diversity on the island."}]$lyceon_json$::jsonb, 'A', NULL, E'The underlined sentence presents a concrete data point—sixty vascular plant species cataloged by 2009—that extends the narrative of ecological colonization from the earlier mention of mosses and lichens. It therefore serves as a specific detail illustrating the progression of that colonization. The choice about introducing a hypothesis is wrong because no hypothesis is proposed in the sentence; it simply reports a factual finding. The choice about challenging the contamination claim is wrong because the sentence''s content about plant diversity does not contradict the restriction on human access. The choice about explaining methodology is wrong because the sentence reports results (species counted) without describing how the survey was conducted.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2ZMAMRL', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 2, 'mcq', E'A student is writing an essay about textile history for an art history course. The student wants to present a contrast between the traditional and modern uses of indigo dye. Which choice most effectively uses the relevant information from the notes to accomplish this goal?
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2ZQT2WI', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The archaeologist''s team uncovered seventeen clay tablets at an excavation site near the ancient settlement of Dholavira. The three tablets ______ contained inscriptions matching a script found only in a single comparable trove from Lothal were immediately transferred under nitrogen-sealed glass to the Gujarat State Museum, where specialists in Indus Valley epigraphy could examine them without risk of oxidative damage.', $lyceon_json$[{"key":"A","text":"tablets, that contained"},{"key":"B","text":"tablets; that contained"},{"key":"C","text":"tablets that contained"},{"key":"D","text":"tablets. That contained"}]$lyceon_json$::jsonb, 'C', NULL, E'The clause "that contained inscriptions matching a script found only in a single comparable trove from Lothal" is a restrictive relative clause identifying which three tablets were transferred. Restrictive clauses require no punctuation before them; adding a comma before "that" incorrectly treats the clause as nonrestrictive and violates standard convention. A semicolon before "that" would sever the relative clause from its antecedent, breaking the sentence structure. A period before "That" would strand "That contained inscriptions...were immediately transferred" as a malformed sentence beginning with a relative pronoun that lacks a proper independent clause structure.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"sentence_boundary_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
